"""hft_csr (generated by PeakRDL-regblock from firmware/rdl/hft_csr.rdl): AXI4-Lite access to the
bare register block.

The expected values are written by hand here (not read from the RDL), so a change of the map
that nobody meant shows up as a failing test.
"""

import random

import cocotb
from cocotb.triggers import RisingEdge
from cocotbext.axi import AxiLiteBus, AxiLiteMaster, AxiResp

from common.clocks import start_clock
from common.runner import run_cocotb

PERIOD_PS = 4000  # host_clk, 250 MHz

ID = 0x0000
VERSION = 0x0004
SCRATCH = 0x0008
UNMAPPED = 0xFFFC  # top of the 64 KiB window: never mapped


async def start(dut) -> AxiLiteMaster:
    """Idle inputs, reset, then the clock (no edge with undriven inputs)."""
    for name in ("awvalid", "wvalid", "bready", "arvalid", "rready"):
        getattr(dut, f"s_axil_{name}").value = 0
    dut.rst.value = 1
    start_clock(dut.clk, PERIOD_PS)
    for _ in range(4):
        await RisingEdge(dut.clk)
    dut.rst.value = 0
    await RisingEdge(dut.clk)
    return AxiLiteMaster(AxiLiteBus.from_prefix(dut, "s_axil"), dut.clk, dut.rst)


async def read32(axil: AxiLiteMaster, addr: int) -> tuple[int, AxiResp]:
    r = await axil.read(addr, 4)
    return int.from_bytes(r.data, "little"), r.resp


async def write32(axil: AxiLiteMaster, addr: int, value: int) -> AxiResp:
    return (await axil.write(addr, value.to_bytes(4, "little"))).resp


@cocotb.test(timeout_time=100, timeout_unit="us")  # a broken DUT must fail, not hang
async def tc_smoke(dut):
    """ID and VERSION read their constants, SCRATCH reads back what was written, an unmapped
    address and a write to a read-only register answer SLVERR without a side effect."""
    axil = await start(dut)
    assert await read32(axil, ID) == (0x48465431, AxiResp.OKAY)
    assert await read32(axil, VERSION) == (0x0005_0000, AxiResp.OKAY)
    assert await read32(axil, SCRATCH) == (0, AxiResp.OKAY), "SCRATCH reset value"
    for _ in range(8):
        value = random.getrandbits(32)
        assert await write32(axil, SCRATCH, value) == AxiResp.OKAY
        assert await read32(axil, SCRATCH) == (value, AxiResp.OKAY)
    assert (await read32(axil, UNMAPPED))[1] == AxiResp.SLVERR
    assert await write32(axil, UNMAPPED, 0x1234_5678) == AxiResp.SLVERR
    assert await write32(axil, ID, 0) == AxiResp.SLVERR
    assert await read32(axil, ID) == (0x48465431, AxiResp.OKAY), "a rejected write changed ID"
    assert await read32(axil, SCRATCH) == (value, AxiResp.OKAY), "a rejected write changed SCRATCH"


def test_hft_csr():
    run_cocotb(toplevel="hft_csr", filelists=["common.f", "csr.f"], test_module="test_hft_csr")
